<script setup lang="ts">
import { computed } from 'vue';
import type { PublicationPlan } from '../../types/publication';
import { reviewSituation } from '../../utils/reviewSituation';
import { reportAuthorGoal, reportLimitations, reportValidationLabel, reportSourceLink, publicationFindingTitle } from '../../utils/reportPresentation';
import AppIcon from '../common/AppIcon.vue';
import PrDiscussionContext from '../review/PrDiscussionContext.vue';
const props = defineProps<{ plan: PublicationPlan; prUrl?: string }>();
const emit = defineEmits<{ file: [path: string]; finding: [key: string] }>();
const situation = computed(() => reviewSituation(props.plan));
const digest = computed(() => props.plan.digest);
const understanding = computed(() => digest.value.change_understanding);
const observations = computed(() => (digest.value.intent_assessments || []).flatMap(intent => intent.observations.map(observation => ({ ...observation, target: intent.author_target }))));
const findings = computed(() => [...props.plan.inline_drafts, ...props.plan.summary_findings]);
const limitations = computed(() => reportLimitations(props.plan).filter(item => item !== digest.value.author_context_limitation));
const alignmentLabel = { supported: '局部证据支持', contradicted: '存在相反证据', insufficient: '证据不足', not_applicable: '不适用' };
const sourceLink = (path: string, side: 'head' | 'base' | null, line: number | null) => reportSourceLink(props.prUrl || digest.value.pr_url,
  path, side === 'head' ? props.plan.snapshot.head_sha : side === 'base' ? props.plan.snapshot.effective_base_sha : null, line);
</script>
<template>
  <div class="rd-doc">
    <PrDiscussionContext :review-id="plan.review_id" :stats="digest.discussion_stats" />
    <section id="rd-detail-conclusion" class="rd-detail-intro" :class="situation?.tone"><h3><AppIcon :name="situation?.icon || 'help'" :size="20" />{{ situation?.title || '审查结论未知' }}</h3><p>{{ situation?.description }} 覆盖情况、证据可靠性和动态验证属于不同维度。</p></section>
    <div class="rd-metric-strip"><div><strong>{{ plan.outcome.confirmed_count ?? '未知' }}</strong><small>已确认问题</small></div><div><strong>{{ plan.outcome.examined_goals ?? '?' }} / {{ plan.outcome.total_goals ?? '?' }}</strong><small>约定目标检查情况</small></div><div><strong class="rd-validation-value">{{ reportValidationLabel(plan.outcome.dynamic_validation) }}</strong><small>目标仓库动态验证</small></div></div>
    <section id="rd-detail-changes" class="rd-doc-section"><h3><span class="rd-num">01</span>这次 PR 想解决什么？</h3><div class="rd-two-col"><div class="rd-info-panel"><h4>PR 目标</h4><p>{{ reportAuthorGoal(plan) }}</p></div><div class="rd-info-panel"><h4>代码变化 · 局部静态观察</h4><p v-if="understanding?.actual_changes">{{ understanding.actual_changes }}</p><ul v-else-if="digest.actual_changes?.length"><li v-for="(change, index) in digest.actual_changes" :key="index">{{ change }}</li></ul><p v-else>尚无归纳后的代码变化记录。</p></div></div><div v-if="understanding?.alignment" class="rd-notice warn rd-space"><AppIcon name="info" :size="17" /><div>{{ understanding.alignment }}</div></div></section>
    <section id="rd-detail-evidence" class="rd-doc-section"><h3><span class="rd-num">02</span>核对到的代码依据</h3><p>下列观察和问题均来自本轮计划。文件位置与证据引用保留服务端提供的对应关系。</p>
      <article v-for="(observation, index) in observations" :key="`${observation.goal_id}:${index}`" class="rd-evidence"><header><strong>{{ observation.target }}</strong><span class="badge" :class="observation.alignment === 'supported' ? 'success' : 'warning'">{{ alignmentLabel[observation.alignment] || observation.alignment }}</span></header><button type="button" class="rd-path" @click="emit('file', observation.path)">{{ observation.path }}{{ observation.start_line ? ` · L${observation.start_line}` : '' }} · {{ observation.side === 'base' ? 'Base' : 'Head' }}<AppIcon name="arrow-right" :size="13" /></button><a v-if="sourceLink(observation.path, observation.side, observation.start_line)" class="rd-source-link" :href="sourceLink(observation.path, observation.side, observation.start_line)!" target="_blank" rel="noreferrer">查看快照源码 ↗</a><p>{{ observation.actual_behavior }}</p><div v-if="observation.evidence_ids.length" class="rd-evidence-ids"><code v-for="id in observation.evidence_ids" :key="id">{{ id }}</code></div><ul v-if="observation.limitations.length"><li v-for="(item, i) in observation.limitations" :key="i">{{ item }}</li></ul></article>
      <article v-for="finding in findings" :key="finding.finding_key" class="rd-evidence"><header><button type="button" class="rd-text-button" @click="emit('finding', finding.finding_key)">{{ publicationFindingTitle(finding) }}</button><span class="badge" :class="['critical', 'high'].includes(finding.severity) ? 'danger' : 'warning'">{{ ({ critical: '严重', high: '高', medium: '中', low: '低' })[finding.severity] }}</span></header><button type="button" class="rd-path" @click="emit('file', finding.anchor.file_path)">{{ finding.anchor.file_path || '未提供文件' }}{{ finding.anchor.start_line ? ` · L${finding.anchor.start_line}${finding.anchor.end_line && finding.anchor.end_line !== finding.anchor.start_line ? `–${finding.anchor.end_line}` : ''}` : '' }} · {{ finding.anchor.side === 'base' ? 'Base' : finding.anchor.side === 'head' ? 'Head' : '侧别未知' }}<AppIcon name="arrow-right" :size="13" /></button><a v-if="sourceLink(finding.anchor.file_path, finding.anchor.side, finding.anchor.start_line)" class="rd-source-link" :href="sourceLink(finding.anchor.file_path, finding.anchor.side, finding.anchor.start_line)!" target="_blank" rel="noreferrer">查看快照源码 ↗</a><p>{{ finding.evidence_summary || finding.affected_behavior }}</p><p v-if="finding.recommendation"><strong>建议：</strong>{{ finding.recommendation }}</p><div class="rd-evidence-ids"><code v-for="id in finding.evidence_ids" :key="id">{{ id }}</code></div></article>
      <p v-if="!observations.length && !findings.length" class="rd-empty-note">本轮没有可展示的逐项代码观察或已确认问题。可在技术记录中查看目标记录；这不表示所有业务路径均已核验。</p>
    </section>
    <section id="rd-detail-gaps" class="rd-doc-section"><h3><span class="rd-num">03</span>尚未核验的部分</h3><ul v-if="limitations.length" class="rd-check-list"><li v-for="(item, index) in limitations" :key="index"><AppIcon name="alert" :size="15" /><span>{{ item }}</span></li></ul><p v-else>本轮未提供额外局限记录；静态检查不能证明全部业务路径正确。</p><h4>来源与验证边界</h4><p v-if="reportAuthorGoal(plan) !== '未记录明确的作者目标。'">PR 目标来自作者提供的 PR 描述或标题，以本轮保存的内容为准；仅作审查背景，不代表目标已实现。</p><p v-if="digest.author_context_limitation">{{ digest.author_context_limitation }}</p><div class="rd-notice"><AppIcon name="flask" :size="17" /><div>动态验证：{{ reportValidationLabel(plan.outcome.dynamic_validation) }}。<template v-if="plan.outcome.dynamic_validation === 'not_executed'">未执行目标仓库代码、测试或构建。读取测试源码不等于测试通过。</template><template v-else>请结合以下来源、阶段与快照记录判断，不能将独立补丁结果视为当前 Head 通过。</template></div></div><ul v-if="digest.validations?.length"><li v-for="item in digest.validations" :key="item.id">{{ item.source }} / {{ item.stage }}：{{ item.status }}。{{ item.reason }}</li></ul></section>
    <section id="rd-detail-actions" class="rd-doc-section"><h3><span class="rd-num">04</span>建议下一步</h3><p>{{ digest.merge_decision?.advice || '核对未决证据、业务预期与项目 CI，在提交变化后重新审查受影响内容。' }}</p><p v-if="digest.termination_reason" class="rd-empty-note">终止原因：{{ digest.termination_reason }}</p></section>
  </div>
</template>
